document.addEventListener("DOMContentLoaded",function(){const slider=document.querySelector(".slider");const slides=document.querySelectorAll(".slider__item");const prevButton=document.querySelector(".slider__prev");const nextButton=document.querySelector(".slider__next");let currentIndex=0;let startX,endX;const totalSlides=slides.length;const counterLine=document.querySelector(".slider__counter-line");const counterNum=document.querySelector(".slider__counter-num");const stepSize=(94-41)/(totalSlides-1);const slideIntervalTime=5e3;let slideInterval;function ImageToCenter(slide){const image=slide.querySelector(".slider__image img");const sliderWidth=slide.offsetWidth;const sliderHeight=slide.offsetHeight;slide.style.position="relative";image.style.position="absolute";image.style.top="50%";image.style.left="50%";image.style.transform="translate(-50%, -50%)";image.style.width="auto";image.style.height="auto";image.onload=()=>{const imageWidth=image.naturalWidth;const imageHeight=image.naturalHeight;if(imageWidth>sliderWidth){image.style.width="auto";image.style.left=`50%`}else{image.style.width="100%"}if(imageHeight>sliderHeight){image.style.height="auto";image.style.top=`50%`}else{image.style.height="100%"}};if(image.complete){image.onload()}}function loadSlideImage(slide){var image=slide.querySelector(".slider__image img");var src=image.getAttribute("data-slide-src");if(src){image.src=src}}var accordionItems=document.querySelectorAll(".slider__accordion-item");accordionItems.forEach(function(item){item.addEventListener("click",function(){this.classList.toggle("active")})});function updateCounterLine(index){const newPosition=index*stepSize;counterLine.style.setProperty("--counter-line-position",`${newPosition}px`)}function updateCounterNum(index){counterNum.textContent=String(index+1).padStart(2,"0")}function showSlide(index){const offset=index*-100;slides.forEach((slide,i)=>{slide.style.transition="transform 0.5s ease-in-out";slide.style.transform=`translateX(${offset}%)`;if(i===index){slide.classList.add("active");loadSlideImage(slide);ImageToCenter(slide)}else{slide.classList.remove("active")}});updateCounterLine(index);updateCounterNum(index)}function startSlideInterval(){slideInterval=setInterval(()=>{currentIndex=(currentIndex+1)%slides.length;showSlide(currentIndex)},slideIntervalTime)}function stopSlideInterval(){clearInterval(slideInterval)}nextButton.addEventListener("click",()=>{stopSlideInterval();currentIndex=(currentIndex+1)%slides.length;showSlide(currentIndex);startSlideInterval()});prevButton.addEventListener("click",()=>{stopSlideInterval();currentIndex=(currentIndex-1+slides.length)%slides.length;showSlide(currentIndex);startSlideInterval()});slider.addEventListener("touchstart",function(e){stopSlideInterval();startX=e.touches[0].pageX});slider.addEventListener("touchend",function(e){endX=e.changedTouches[0].pageX;handleSwipe();startSlideInterval()});slider.addEventListener("mousedown",function(e){stopSlideInterval();startX=e.pageX;slider.style.cursor="grabbing"});slider.addEventListener("mouseup",function(e){endX=e.pageX;slider.style.cursor="grab";handleSwipe();startSlideInterval()});function handleSwipe(){if(startX-endX>100){currentIndex=(currentIndex+1)%slides.length}else if(endX-startX>100){currentIndex=(currentIndex-1+slides.length)%slides.length}showSlide(currentIndex)}window.addEventListener("resize",()=>{ImageToCenter(slides[currentIndex])});showSlide(currentIndex);startSlideInterval()});